// ---------------------------------------------------------------------------
// Parse + schema validation (edge filtering)
// Output 1: valid message   Output 2: rejected -> dead-letter topic
// Mirrors schemas/telemetry.schema.json & event.schema.json with cheap
// hand-written checks (full JSON-Schema validation per message is too slow
// for thousands of messages per second in a single Node-RED instance).
// ---------------------------------------------------------------------------
const stats = global.get('stats');
const kind = msg.topic.endsWith('/events') ? 'event' : 'telemetry';
stats.received[kind]++;

function reject(reason) {
    stats.rejected++;
    stats.rejectReasons[reason] = (stats.rejectReasons[reason] || 0) + 1;
    const raw = typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload);
    msg.kafkaTopic = env.get('KAFKA_TOPIC_DLQ') || 'vehicle.dlq';
    msg.kafkaKey = (msg.topic.split('/')[1] || 'unknown');
    msg.payload = {
        reason: reason,
        mqtt_topic: msg.topic,
        received_at: new Date().toISOString(),
        raw: raw ? raw.slice(0, 2000) : null
    };
    return [null, msg];
}

let d = msg.payload;
if (Buffer.isBuffer(d)) d = d.toString('utf8');
if (typeof d === 'string') {
    try { d = JSON.parse(d); } catch (e) { return reject('invalid_json'); }
}
if (d === null || typeof d !== 'object' || Array.isArray(d)) return reject('not_an_object');

const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const inRange = (v, lo, hi) => isNum(v) && v >= lo && v <= hi;
const optNum = (v, lo, hi) => v === null || v === undefined || inRange(v, lo, hi);

if (typeof d.vehicle_id !== 'string' || !/^vehicle-\d{5,6}$/.test(d.vehicle_id)) return reject('bad_vehicle_id');
if (msg.topic.split('/')[1] !== d.vehicle_id) return reject('topic_vehicle_mismatch');
if (typeof d.message_id !== 'string' || d.message_id.length < 8) return reject('missing_message_id');
const ts = Date.parse(d.timestamp);
if (!Number.isFinite(ts)) return reject('bad_timestamp');
const now = Date.now();
if (ts > now + 5000) return reject('timestamp_in_future');
if (now - ts > 24 * 3600 * 1000) return reject('timestamp_too_old');

if (kind === 'event') {
    const TYPES = ['COLLISION_WARNING', 'OBSTACLE_DETECTED', 'SUDDEN_BRAKING', 'LOW_BATTERY', 'CRITICAL_BATTERY',
        'SENSOR_FAILURE', 'ABNORMAL_SPEED', 'ROUTE_DEVIATION', 'EMERGENCY_STOP'];
    const SEV = ['INFO', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
    if (!TYPES.includes(d.event_type)) return reject('unknown_event_type');
    if (!SEV.includes(d.severity)) return reject('bad_severity');
} else {
    const L = d.location, B = d.battery, V = d.vehicle;
    if (!L || typeof L !== 'object') return reject('missing_location');
    if (!inRange(L.latitude, -90, 90) || !inRange(L.longitude, -180, 180)) return reject('bad_coordinates');
    if (!inRange(L.speed_kmh, 0, 400)) return reject('bad_speed');
    if (!inRange(L.heading, 0, 360)) return reject('bad_heading');
    if (!B || !inRange(B.percentage, 0, 100) || typeof B.charging !== 'boolean') return reject('bad_battery');
    if (!V || !['AVAILABLE', 'IN_SERVICE', 'IDLE', 'CHARGING', 'MAINTENANCE', 'EMERGENCY'].includes(V.status)) return reject('bad_vehicle_status');
    if (!Number.isInteger(V.passenger_count) || V.passenger_count < 0 || V.passenger_count > 6) return reject('bad_passenger_count');
    if (!d.lidar || !optNum(d.lidar.distance_m, 0, 300)) return reject('bad_lidar');
    if (!d.radar || !optNum(d.radar.distance_m, 0, 300)) return reject('bad_radar');
    if (!d.camera || !optNum(d.camera.confidence, 0, 1)) return reject('bad_camera');
    if (!d.traffic || !['LOW', 'MODERATE', 'HIGH', 'CONGESTED'].includes(d.traffic.status)) return reject('bad_traffic');
}
msg.kind = kind;
msg.payload = d;
msg.generatedAt = ts;
return [msg, null];

// ---------------------------------------------------------------------------
// De-duplication + sequence tracking
// A bounded "seen" set of message_ids (two rotating generations, so memory is
// capped) drops duplicates caused by QoS-1 redelivery, store-and-forward
// replays or faulty senders. Sequence gaps / reordering are counted, not dropped.
// ---------------------------------------------------------------------------
const stats = global.get('stats');
const MAX = Number(env.get('DEDUPE_WINDOW') || 200000);
let cur = context.get('cur'), old = context.get('old');
if (!cur) { cur = new Set(); old = new Set(); context.set('cur', cur); context.set('old', old); }
const id = msg.payload.message_id;
if (cur.has(id) || old.has(id)) {
    stats.duplicates++;
    return null;
}
cur.add(id);
if (cur.size >= MAX) {                 // rotate generations
    context.set('old', cur);
    context.set('cur', new Set());
}
if (msg.kind === 'telemetry') {
    let seqs = context.get('seqs');
    if (!seqs) { seqs = new Map(); context.set('seqs', seqs); }
    const last = seqs.get(msg.payload.vehicle_id);
    const s = msg.payload.sequence;
    if (last !== undefined && Number.isInteger(s)) {
        if (s <= last) stats.outOfOrder++;
        else if (s > last + 1) stats.sequenceGaps += (s - last - 1);
    }
    if (Number.isInteger(s) && (last === undefined || s > last)) seqs.set(msg.payload.vehicle_id, s);
}
return msg;

// ---------------------------------------------------------------------------
// Filtering + enrichment ("processing pipeline" from the project plan §7)
//  * drops simulator-only debugging fields
//  * adds ingestion metadata (received time, edge latency, pipeline stage)
//  * derives a priority flag so critical telemetry can be spotted downstream
//  * chooses the Kafka topic and partition key (vehicle_id => per-vehicle ordering)
// ---------------------------------------------------------------------------
const stats = global.get('stats');
const d = msg.payload;
const now = Date.now();
const edgeLatency = now - msg.generatedAt;

if (d.simulation) delete d.simulation.malformed_kind;
d.ingest = {
    received_at: new Date(now).toISOString(),
    edge_latency_ms: edgeLatency,
    gateway: env.get('HOSTNAME') || 'node-red',
    mqtt_topic: msg.topic
};

// reservoir of recent edge latencies for /stats percentiles
const lat = stats.latency[msg.kind];
lat.push(edgeLatency);
if (lat.length > 20000) lat.splice(0, lat.length - 20000);

if (msg.kind === 'event') {
    d.ingest.priority = (d.severity === 'CRITICAL' || d.severity === 'HIGH') ? 'HIGH' : 'NORMAL';
    msg.kafkaTopic = env.get('KAFKA_TOPIC_EVENTS') || 'vehicle.events';
    stats.forwarded.event++;
} else {
    const s = d.safety || {};
    const critical = s.emergency_braking === true ||
        (typeof s.time_to_collision_s === 'number' && s.time_to_collision_s < 3) ||
        d.vehicle.status === 'EMERGENCY';
    d.location.speed_mps = Math.round(d.location.speed_kmh / 3.6 * 100) / 100;   // unit conversion
    d.ingest.priority = critical ? 'HIGH' : 'NORMAL';
    msg.kafkaTopic = env.get('KAFKA_TOPIC_TELEMETRY') || 'vehicle.telemetry';
    stats.forwarded.telemetry++;
}
msg.kafkaKey = d.vehicle_id;
return msg;

// ---------------------------------------------------------------------------
// Kafka producer (kafkajs) with micro-batching
// Messages are buffered and flushed every KAFKA_LINGER_MS or KAFKA_BATCH_SIZE
// messages, whichever comes first. If Kafka is unavailable the buffer keeps
// messages (bounded by KAFKA_MAX_BUFFER, oldest dropped and counted) and
// retries - Node-RED keeps accepting MQTT traffic meanwhile.
// ---------------------------------------------------------------------------
const st = context.get('state');
if (!st) return null;
st.buffer.push({ topic: msg.kafkaTopic, key: msg.kafkaKey, value: JSON.stringify(msg.payload) });
if (st.buffer.length > st.maxBuffer) {
    const drop = st.buffer.length - st.maxBuffer;
    st.buffer.splice(0, drop);
    global.get('stats').kafka.dropped += drop;
}
if (st.buffer.length >= st.batchSize && !st.flushing) st.flush();
return null;

initialize:
// On Start: create the kafkajs producer and the flush loop
const stats = global.get('stats');
const enabled = String(env.get('KAFKA_ENABLED') || 'true').toLowerCase() !== 'false';
const st = {
    buffer: [], flushing: false, connected: false, producer: null,
    batchSize: Number(env.get('KAFKA_BATCH_SIZE') || 500),
    maxBuffer: Number(env.get('KAFKA_MAX_BUFFER') || 200000),
    linger: Number(env.get('KAFKA_LINGER_MS') || 20)
};
context.set('state', st);
stats.kafka.enabled = enabled;

st.flush = async function () {
    if (st.flushing || st.buffer.length === 0) return;
    if (!enabled) {                                    // edge-only benchmark mode
        stats.kafka.discardedDisabled += st.buffer.length;
        st.buffer.length = 0;
        return;
    }
    if (!st.connected) return;
    st.flushing = true;
    const batch = st.buffer.splice(0, Math.max(st.batchSize, 2000));
    const byTopic = {};
    for (const m of batch) (byTopic[m.topic] = byTopic[m.topic] || []).push({ key: m.key, value: m.value });
    const topicMessages = Object.keys(byTopic).map(t => ({ topic: t, messages: byTopic[t] }));
    const t0 = Date.now();
    try {
        await st.producer.sendBatch({ topicMessages, acks: -1, timeout: 10000 });
        stats.kafka.sent += batch.length;
        stats.kafka.batches++;
        stats.kafka.lastBatchMs = Date.now() - t0;
    } catch (e) {
        stats.kafka.errors++;
        stats.kafka.lastError = String(e.message || e);
        st.buffer.unshift(...batch);                  // keep order, retry later
        node.status({ fill: 'red', shape: 'ring', text: 'kafka error: ' + stats.kafka.lastError.slice(0, 40) });
    } finally {
        st.flushing = false;
    }
};

st.timer = setInterval(() => {
    st.flush();
    node.status({ fill: st.connected ? 'green' : (enabled ? 'yellow' : 'grey'), shape: 'dot',
        text: (enabled ? (st.connected ? 'connected' : 'connecting') : 'kafka disabled') +
            ' | sent ' + stats.kafka.sent + ' | buf ' + st.buffer.length });
}, st.linger);

if (enabled) {
    const { Kafka, logLevel } = global.get('kafkajs');
    const kafka = new Kafka({
        clientId: 'node-red-' + (env.get('HOSTNAME') || 'edge'),
        brokers: String(env.get('KAFKA_BROKER') || 'kafka:9092').split(','),
        logLevel: logLevel.WARN,
        retry: { initialRetryTime: 300, retries: 1000000 }
    });
    st.producer = kafka.producer({ allowAutoTopicCreation: false, idempotent: false, maxInFlightRequests: 5 });
    const connect = async () => {
        try {
            await st.producer.connect();
            st.connected = true;
            stats.kafka.connected = true;
            node.log('Kafka producer connected to ' + env.get('KAFKA_BROKER'));
        } catch (e) {
            stats.kafka.lastError = String(e.message || e);
            node.warn('Kafka connect failed, retrying in 3s: ' + stats.kafka.lastError);
            setTimeout(connect, 3000);
        }
    };
    st.producer.on(st.producer.events.DISCONNECT, () => { st.connected = false; stats.kafka.connected = false; setTimeout(connect, 3000); });
    connect();
}

finalize:
// On Stop: flush what we can and disconnect cleanly
const st = context.get('state');
if (st) {
    clearInterval(st.timer);
    if (st.producer && st.connected) {
        return Promise.resolve(st.flush()).then(() => st.producer.disconnect()).catch(e => node.warn(e));
    }
}

